async function showPlatformSetup(){homeMain.hidden=true;detailMain.hidden=false;document.title='Launch readiness — BlueMint';if(chartObserver){chartObserver.disconnect();chartObserver=null}detailMain.innerHTML='<div class="token-breadcrumb"><a href="#create">Back to launch</a><span>/ Launch readiness</span></div><h1>The Mint vault.</h1><p>BlueMint uses direct Raydium USDC pools. No LaunchLab platform setup transaction is required.</p><section id="chainStatus" class="integration-status">Checking deployment…</section>';await showChainStatus()}
const routeBeforeSetup=route;route=function(){if(location.hash==='#setup'){showPlatformSetup();return}routeBeforeSetup()};window.addEventListener('hashchange',()=>{if(location.hash==='#setup')showPlatformSetup()});if(location.hash==='#setup')showPlatformSetup();
